# Transfer the person to another sheet by id (a steward only): they arrive there with their grades, names, contact and claims, and leave this sheet; one whose name or alias is already there is merged into that person.
validate:
  class: net.officefloor.hq.app.person.ValidateTransfer
  next: snapshot
# The sheet's figures before the change, so the change can audit what it moved.
snapshot:
  class: net.officefloor.hq.app.rollup.SnapshotRollup
  govern: [ transaction ]
  next: load
load:
  class: net.officefloor.hq.app.person.LoadPerson
  govern: [ transaction ]
  next: transfer
transfer:
  class: net.officefloor.hq.app.person.TransferPerson
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.person.RespondWithPerson
  govern: [ transaction ]
package net.officefloor.hq.app.person;

import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.PathVariable;
import net.officefloor.hq.app.setting.Settings;
import net.officefloor.hq.app.setting.ViewerRefusedException;

public class ValidateTransfer {
    public void validate(@PathVariable("sheetId") String sheetId, @RequestBody TransferRequest request, Out<TransferRequest> body, Settings settings)
            throws InvalidPersonException, ViewerRefusedException {
        settings.refuseViewer(sheetId, request.user());
        String to = request.toSheet() == null ? "" : request.toSheet().trim();
        if (to.isEmpty()) {
            throw new InvalidPersonException("No sheet chosen to transfer to");
        }
        if (to.equals(sheetId)) {
            throw new InvalidPersonException("A person cannot be transferred to their own sheet");
        }
        body.set(new TransferRequest(to, request.user()));
    }
}
